public class ADMEntraIdGroupUserImport extends RunBaseBatch implements BatchRetryable
{
    SysUserMSODSUserTmp tmp;

    UserId              groupId;

    // Cache for Entra ID groups (DisplayName -> ObjectId)
    Map                 entraIdGroupCache;
    boolean             groupCacheLoaded;

    // Cache for Entra ID tenant users (lowercase guid string -> DirectoryHelper.User)
    // Loaded once per run via a tenant-wide ListUsers() call.
    Map                 tenantUserCache;
    boolean             tenantUserCacheLoaded;

    // Cache for per-user group memberships (lowercase user objectId -> Container of lowercase group objectIds)
    // Populated once per run via GetSecurityMemberGroupsForUser for every user in tenantUserCache.
    // Used by importUsersFromEntraIdGroup to filter group members without a direct group-member API call.
    Map                 userGroupsCache;
    boolean             userGroupsCacheLoaded;

    // Run-level telemetry counters (populated across all groups in one run)
    int totalMembersFetched;
    int totalUsersCreated;
    int totalSkippedExisting;
    int totalSkippedLiveId;
    int totalSkippedNotInCache;
    int totalErrors;
    int groupsProcessed;
}

