/// <summary>
/// Indicates whether the job can run in batch mode.
/// </summary>
/// <returns>
/// Always returns true.
/// </returns>
public boolean canGoBatch()
{
    return true;
}

/// <summary>
///    Determines whether the class is shown in the list of <c>Journal</c> types.
/// </summary>
/// <returns>
///    true if the class is shown in the list of <c>Journal</c> types; otherwise, false.
/// </returns>
public boolean canGoBatchJournal()
{
    return true;
}

protected boolean canRunInNewSession()
{
    return false;
}

/// <summary>
/// Ensures that ADMEntraIdGroupDynamicRoleAssignment records exist for all Entra ID groups.
/// Creates missing records with the default automatic role assignment setting.
/// </summary>
private void ensureDynamicRoleAssignmentRecords()
{
    ADMEntraIdGroupDynamicRoleAssignment    entraIdGroupDynamicRoleAssignmentNew;
    ADMEntraIdGroupDynamicRoleAssignment    entraIdGroupDynamicRoleAssignmentExist;
    UserInfo                                userInfo;
    NoYes                                   automaticRoleAssignment = ADMParameters::find().AutomaticRoleAssignment;

    ttsbegin;

    insert_recordset entraIdGroupDynamicRoleAssignmentNew (UserInfo, AutomaticRoleAssignment)
        select RecId, automaticRoleAssignment from userInfo
        where userInfo.accountType == UserAccountType::ClaimsGroup
           && userInfo.isMicrosoftAccount == false
           && (!groupId || userInfo.id == groupId)
            notexists join entraIdGroupDynamicRoleAssignmentExist
            where entraIdGroupDynamicRoleAssignmentExist.UserInfo == userInfo.RecId;

    ttscommit;
}

/// <summary>
/// Updates the UserInfo record with the Entra ID group ObjectId.
/// </summary>
/// <param name="_groupUserInfo">The UserInfo record to update.</param>
/// <param name="_objectId">The ObjectId to set.</param>
private void updateGroupObjectId(UserInfo _groupUserInfo, str _objectId)
{
    UserInfo updateUserInfo;

    ttsbegin;

    select forupdate updateUserInfo
        where updateUserInfo.RecId == _groupUserInfo.RecId;

    if (updateUserInfo.RecId)
    {
        updateUserInfo.ObjectId = str2Guid(_objectId);
        updateUserInfo.update();
    }

    ttscommit;
}

/// <summary>
/// Get Entra ID/AD environment.
/// </summary>
/// <returns>
/// true if environment is GraphAPI, else it is Active Directory.
/// </returns>
public static boolean isGraphAPI()
{
    return Microsoft.Dynamics.AX.Security.DirectoryHelper.DirectoryClientProvider::IsGraphAPI();
}

/// <summary>
/// Indicates whether the batch task is run on the server or on a client.
/// </summary>
/// <returns>
/// Always returns true.
/// </returns>
[Microsoft.Dynamics.BusinessPlatform.SharedTypes.InternalUseOnlyAttribute]
public boolean runsImpersonated()
{
    return true;
}

/// <summary>
/// Constructs a new class instance.
/// </summary>
/// <returns>An instance of the <c>ADMEntraIdGroupUserImport</c> class.</returns>
[Microsoft.Dynamics.BusinessPlatform.SharedTypes.InternalUseOnlyAttribute]
public static ADMEntraIdGroupUserImport construct()
{
    return new ADMEntraIdGroupUserImport();
}

private static ClassDescription description()
{
    return "@D365FOAdminToolkit:ImportUsersEntraIdGroupMembership";
}

/// <summary>
/// Microsoft internal use only.
/// </summary>
/// <param name="_args">An instance of the <c>Args</c> class.</param>
[Microsoft.Dynamics.BusinessPlatform.SharedTypes.InternalUseOnlyAttribute]
public static void main(Args _args)
{
    ADMEntraIdGroupUserImport entraIdGroupUserImport = ADMEntraIdGroupUserImport::construct();

    if (entraIdGroupUserImport.prompt())
    {
        entraIdGroupUserImport.runOperation();
    }
}

public UserId parmGroupId(UserId _groupId = groupId)
{
    groupId = _groupId;
    return groupId;
}

/// <summary>
/// Runs the Import users from Entra ID group membership job as a static method.
/// </summary>
/// <param name="_groupId">
/// A group for which to perform the user import; optional.
/// </param>
public server static void synchronize(UserId _groupId = '')
{
    ADMEntraIdGroupUserImport entraIdGroupUserImport = new ADMEntraIdGroupUserImport();
    entraIdGroupUserImport.parmGroupId(_groupId);
    entraIdGroupUserImport.runOperation();
}

/// <summary>
/// Specifies if the batch task is retryable for transient exceptions or not.
/// </summary>
/// <returns>
/// If true is returned, the batch task is retryable, otherwise it is not.
/// </returns>
[Hookable(false)]
public final boolean isRetryable()
{
    return true;
}

/// <summary>
/// Populates the temporary user record from a Graph API user object.
/// </summary>
/// <param name="_graphUser">The Graph API user object.</param>
/// <param name="_axaptaUserManager">The user manager instance.</param>
/// <returns>
/// true if the temporary record was populated and the user is a candidate for import;
/// false if the user is a LiveId / non-resolvable account and should be skipped.
/// </returns>
private boolean populateTmpUserFromGraphUser(
    Microsoft.Dynamics.AX.Security.DirectoryHelper.User _graphUser,
    xAxaptaUserManager _axaptaUserManager)
{
    tmp.clear();

    // Check if user is external (has #EXT# in UPN)
    if (strScan(_graphUser.UserPrincipalName, ADMConstants::Ext, 1, strLen(_graphUser.UserPrincipalName)) == 0)
    {
        // Internal user
        tmp.NetworkAlias = _graphUser.UserPrincipalName;
        tmp.NetworkDomain = Microsoft.Dynamics.ApplicationPlatform.Environment.EnvironmentFactory::GetApplicationEnvironment().get_Provisioning().get_AdminIdentityProvider();
    }
    else if (_graphUser.Mail != '')
    {
        // External user from different Entra ID tenant
        tmp.NetworkAlias = _graphUser.Mail;
        System.Net.Mail.MailAddress mailAddress = new System.Net.Mail.MailAddress(_graphUser.Mail);
        tmp.NetworkDomain = System.String::Format(
            System.Globalization.CultureInfo::InvariantCulture,
            Microsoft.Dynamics.ApplicationPlatform.Environment.EnvironmentFactory::GetApplicationEnvironment().Aad.AADIssuerNameFormat,
            mailAddress.Host);
    }
    else
    {
        // LiveId accounts or external users with no mail - cannot be imported
        warning(strFmt("@D365FOAdminToolkit:EntraIdUserLiveIdSkipped", _graphUser.UserPrincipalName));
        return false;
    }

    tmp.DisplayName = _graphUser.DisplayName;
    tmp.EmailAddress = tmp.NetworkAlias;
    tmp.ObjectId = _graphUser.ObjectID;
    tmp.UserSid = _axaptaUserManager.getUserSid(tmp.NetworkAlias, tmp.NetworkDomain);

    return true;
}

/// <summary>
/// Loads all Entra ID security groups into a cache (called only once per run).
/// </summary>
private void ensureGroupCacheLoaded()
{
    Microsoft.Dynamics.AX.Security.MicrosoftGraphHelper.MicrosoftGraphClient graphClient;
    Microsoft.Dynamics.AX.Security.DirectoryHelper.Group graphGroup;
    System.Collections.IEnumerator groupsEnumerator;

    if (groupCacheLoaded)
    {
        return;
    }

    entraIdGroupCache = new Map(Types::String, Types::String);

    try
    {
        info("@D365FOAdminToolkit:EntraIdGroupCacheLoading");

        graphClient = SysUserMSODSImportHelper::getMicrosoftGraphClient();
        groupsEnumerator = graphClient.ListSecurityGroups().GetEnumerator();

        while (groupsEnumerator.MoveNext())
        {
            graphGroup = groupsEnumerator.Current;

            // Store with lowercase key for case-insensitive lookup
            // Note: Group class uses ObjectID (field) not ObjectId (property)
            if (graphGroup.DisplayName && graphGroup.ObjectID != emptyGuid())
            {
                entraIdGroupCache.insert(strLwr(graphGroup.DisplayName), guid2Str(graphGroup.ObjectID));
            }
        }

        info(strFmt("@D365FOAdminToolkit:EntraIdGroupCacheLoaded", entraIdGroupCache.elements()));
    }
    catch (Exception::CLRError)
    {
        System.Exception ex  = CLRInterop::getLastException();
        str              exMsg = ex ? ex.get_Message() : "unknown";

        SysSecurity::HandleGraphAPIHelperException();
        error(strFmt("@D365FOAdminToolkit:EntraIdGroupCacheErrorDetailed", exMsg));
    }

    groupCacheLoaded = true;
}

/// <summary>
/// Looks up the Entra ID group ObjectId by the group name using cached data.
/// </summary>
/// <param name="_groupName">The name of the group to look up.</param>
/// <returns>The ObjectId of the group, or empty string if not found.</returns>
private str lookupGroupObjectIdByName(str _groupName)
{
    str             foundObjectId = '';
    MapEnumerator   mapEnum;
    int             sampleCount;
    str             sampleKeys;

    if (!_groupName)
    {
        return foundObjectId;
    }

    // Ensure the cache is loaded (only loads once)
    this.ensureGroupCacheLoaded();

    // Lookup using lowercase key
    if (entraIdGroupCache && entraIdGroupCache.exists(strLwr(_groupName)))
    {
        foundObjectId = entraIdGroupCache.lookup(strLwr(_groupName));
        info(strFmt("@D365FOAdminToolkit:EntraIdGroupFoundByName", _groupName, foundObjectId));
    }
    else
    {
        // Cache miss — log up to 3 sample keys so operators can spot name-format drift
        if (entraIdGroupCache)
        {
            mapEnum = entraIdGroupCache.getEnumerator();

            while (mapEnum.moveNext() && sampleCount < 3)
            {
                sampleKeys += (sampleKeys ? ", " : "") + mapEnum.currentKey();
                sampleCount++;
            }

            warning(strFmt("@D365FOAdminToolkit:EntraIdGroupNameNotFound",
                _groupName,
                entraIdGroupCache.elements(),
                sampleKeys));
        }
        else
        {
            warning(strFmt("@D365FOAdminToolkit:EntraIdGroupNameNotFound", _groupName, 0, ''));
        }
    }

    return foundObjectId;
}

private void createUser(SysUserMSODSUserTmp _userToImport, UserId _groupUserId)
{
    UserInfo            ui, groupRecord;
    SysUserInfo         sui;
    str                 lastInfoLog;
    xAxaptaUserManager  axaptaUserManager = new xAxaptaUserManager();

    ttsbegin;

    // Select the group record for default settings
    select firstonly Id, Company, Language, HelpLanguage from groupRecord
        where groupRecord.Id == _groupUserId;

    // Insert a row in the UserInfo table
    ui.Id           = _userToImport.AxUserID;
    ui.NetworkAlias = _userToImport.NetworkAlias;
    ui.NetworkDomain = _userToImport.NetworkDomain;
    ui.AccountType  = UserAccountType::ClaimsUser;
    ui.ObjectId     = _userToImport.ObjectId;
    ui.Name         = _userToImport.DisplayName;
    ui.Enable       = true;
    ui.EnabledOnce  = true;
    ui.Company      = groupRecord.Company;
    ui.Language     = groupRecord.Language;
    ui.Helplanguage = groupRecord.Helplanguage;
    ui.IdentityProvider = Microsoft.Dynamics.AX.Security.AuthenticationCommon.AadHelper::GetCanonicalIdentityProvider(ui.NetworkDomain);

    if (_userToImport.UserSid != '')
    {
        ui.sid = _userToImport.UserSid;
    }
    else
    {
        try
        {
            ui.Sid = axaptaUserManager.getUserSid(ui.NetworkAlias, ui.IdentityProvider);
        }
        catch (Exception::Error)
        {
            ui.Sid = '';
            warning(strFmt("@D365FOAdminToolkit:EntraIdUserSidLookupFailed", ui.NetworkAlias));
        }
    }

    try
    {
        ui.insert();
    }
    catch (Exception::Error)
    {
        lastInfoLog = infolog.text();
        throw error(strFmt("@D365FOAdminToolkit:EntraIdUserInsertFailed", ui.NetworkAlias, lastInfoLog));
    }

    // If a row for the user id does not exist in the SysUserInfo, add one
    select firstonly RecId from sui
        where sui.Id == ui.Id;

    if (!sui)
    {
        sui.initValue(ui.Id);
        sui.Id = ui.Id;
        sui.Email = _userToImport.EmailAddress;
        sui.insert();
    }

    ttscommit;
}

/// <summary>
/// Runs the operation.
/// </summary>
[Microsoft.Dynamics.BusinessPlatform.SharedTypes.InternalUseOnlyAttribute]
public void run()
{
    UserInfo    groupUserInfo;
    UserInfo    countInfo;
    int         qualifyingGroups;

    // Ensure ADMEntraIdGroupDynamicRoleAssignment records exist for all groups being processed
    this.ensureDynamicRoleAssignmentRecords();

    // Reset run-level counters
    totalMembersFetched    = 0;
    totalUsersCreated      = 0;
    totalSkippedExisting   = 0;
    totalSkippedLiveId     = 0;
    totalSkippedNotInCache = 0;
    totalErrors            = 0;
    groupsProcessed        = 0;

    // Count qualifying groups up-front so we can log an accurate starting line
    select count(RecId) from countInfo
        where countInfo.accountType == UserAccountType::ClaimsGroup
           && countInfo.isMicrosoftAccount == false
           && (!groupId || countInfo.id == groupId);

    qualifyingGroups = int642int(countInfo.RecId);

    info(strFmt("@D365FOAdminToolkit:EntraIdImportStarting", qualifyingGroups));

    // Iterate through all Entra ID groups (or a specific group if groupId is set)
    while select groupUserInfo
        where groupUserInfo.accountType == UserAccountType::ClaimsGroup
           && groupUserInfo.isMicrosoftAccount == false
           && (!groupId || groupUserInfo.id == groupId)
    {
        this.importUsersFromEntraIdGroup(groupUserInfo);
        groupsProcessed++;
    }

    info(strFmt("@D365FOAdminToolkit:EntraIdImportCompleted",
        groupsProcessed,
        totalMembersFetched,
        totalUsersCreated,
        totalSkippedExisting,
        totalSkippedLiveId,
        totalErrors,
        totalSkippedNotInCache));
}

/// <summary>
/// Loads all Entra ID tenant users into a cache (called only once per run).
/// </summary>
/// <remarks>
/// Uses <c>SysUserMSODSImportHelper::getActiveDirectoryClient().ListUsers()</c> — the
/// same API that standard <c>SysUserImportService::bulkImportUsers</c> uses for
/// tenant-wide user enumeration. Returns <c>IEnumerable&lt;DirectoryHelper.User&gt;</c>.
///
/// Keys are stored as lowercase guid strings (via <c>str2Guid</c> → <c>guid2Str</c> → <c>strLwr</c>)
/// so they compare cleanly regardless of input format.
///
/// On Graph failure we still set <c>tenantUserCacheLoaded = true</c> with an empty
/// map so we don't re-try the (potentially slow) ListUsers call for every group in
/// the same run.
/// </remarks>
private void ensureTenantUserCacheLoaded()
{
    Microsoft.Dynamics.AX.Security.DirectoryHelper.User user;
    System.Collections.IEnumerator usersEnumerator;

    if (tenantUserCacheLoaded)
    {
        return;
    }

    tenantUserCache = new Map(Types::String, Types::Class);

    try
    {
        info("@D365FOAdminToolkit:EntraIdTenantCacheLoading");

        usersEnumerator = SysUserMSODSImportHelper::getActiveDirectoryClient().ListUsers().GetEnumerator();

        while (usersEnumerator.MoveNext())
        {
            user = usersEnumerator.Current;

            if (user && user.ObjectID != emptyGuid())
            {
                // Canonicalise the key: guid2Str always emits braced form, strLwr normalises case.
                tenantUserCache.insert(strLwr(guid2Str(user.ObjectID)), user);
            }
        }

        info(strFmt("@D365FOAdminToolkit:EntraIdTenantCacheLoaded", tenantUserCache.elements()));
    }
    catch (Exception::CLRError)
    {
        System.Exception ex    = CLRInterop::getLastException();
        str              exMsg = ex ? ex.get_Message() : "unknown";

        SysSecurity::HandleGraphAPIHelperException();
        error(strFmt("@D365FOAdminToolkit:EntraIdTenantCacheError", exMsg));
    }

    // Set loaded=true even on failure so we don't re-attempt for every group.
    tenantUserCacheLoaded = true;
}

/// <summary>
/// Builds a per-user group-membership cache by calling
/// <c>IDirectoryClient.GetSecurityMemberGroupsForUser</c> for every user
/// in <c>tenantUserCache</c>. Called at most once per run; no-op on subsequent calls.
/// </summary>
/// <remarks>
/// The resulting <c>userGroupsCache</c> maps the lowercase user ObjectId string
/// to a <c>Container</c> of lowercase group ObjectId strings.  This lets
/// <c>importUsersFromEntraIdGroup</c> determine group membership without calling
/// a non-existent <c>GetMembersOfSecurityGroup</c> API that is unavailable in
/// the current platform version.
/// </remarks>
private void ensureUserGroupsCacheLoaded()
{
    Microsoft.Dynamics.AX.Security.DirectoryHelper.IDirectoryClient   dirClient;
    Microsoft.Dynamics.AX.Security.DirectoryHelper.User               cachedUser;
    System.Collections.IEnumerator                                     userGroupsEnumerator;
    MapEnumerator                                                      tenantCacheEnum;
    UserInfo                                                           existingUser;
    Set                                                                existingObjectIds;
    str                                                                userObjectId;
    Container                                                          groupIds;

    if (userGroupsCacheLoaded)
    {
        return;
    }

    userGroupsCache = new Map(Types::String, Types::Container);

    // Build a set of ObjectIds already in D365FO so we can skip Graph calls
    // for users who will be discarded as skippedExisting during import anyway.
    existingObjectIds = new Set(Types::Guid);
    while select ObjectId from existingUser
        where existingUser.ObjectId != emptyGuid()
    {
        existingObjectIds.add(existingUser.ObjectId);
    }

    try
    {
        dirClient = Microsoft.Dynamics.AX.Security.DirectoryHelper.DirectoryClientProvider::GetDirectoryClient();

        tenantCacheEnum = tenantUserCache.getEnumerator();

        while (tenantCacheEnum.moveNext())
        {
            userObjectId = tenantCacheEnum.currentKey();
            cachedUser   = tenantCacheEnum.currentValue();
            groupIds     = conNull();

            if (existingObjectIds.in(cachedUser.ObjectID))
            {
                // User already exists in D365FO; skip the Graph call.
                userGroupsCache.insert(userObjectId, groupIds);
                continue;
            }

            try
            {
                userGroupsEnumerator = dirClient.GetSecurityMemberGroupsForUser(userObjectId).GetEnumerator();

                while (userGroupsEnumerator.MoveNext())
                {
                    groupIds += strLwr(userGroupsEnumerator.Current);
                }
            }
            catch (Exception::CLRError)
            {
                CLRInterop::getLastException();
                // Skip this user; they will be treated as a member of no groups.
            }

            userGroupsCache.insert(userObjectId, groupIds);
        }
    }
    catch (Exception::CLRError)
    {
        System.Exception ex    = CLRInterop::getLastException();
        str              exMsg = ex ? ex.get_Message() : "unknown";
        error(strFmt("@D365FOAdminToolkit:EntraIdTenantCacheError", exMsg));
    }

    userGroupsCacheLoaded = true;
}

/// <summary>
/// Imports users from a specific Entra ID group. Per-group logging is intentionally
/// suppressed; run-level counters are rolled into the summary emitted by <c>run()</c>.
/// </summary>
/// <param name="_groupUserInfo">The UserInfo record representing the Entra ID group.</param>
private void importUsersFromEntraIdGroup(UserInfo _groupUserInfo)
{
    Microsoft.Dynamics.AX.Security.DirectoryHelper.User graphUser;
    SysUserMSODSImportHelper helper = new SysUserMSODSImportHelper();
    List selectedUsers = new List(Types::Record);
    UserInfo existingUser;
    xAxaptaUserManager axaptaUserManager = new xAxaptaUserManager();
    MapEnumerator   tenantCacheEnum;
    str     groupObjectId;
    str     groupObjectIdNorm;
    str     memberObjectIdKey;
    Container memberGroupIds;
    int     i;
    boolean inGroup;
    int     membersFetched;
    int     created;
    int     skippedExisting;
    int     skippedLiveId;
    int     skippedNotInCache;
    int     errors;

    groupObjectId = guid2Str(_groupUserInfo.ObjectId);

    if (!groupObjectId || groupObjectId == guid2Str(emptyGuid()))
    {
        groupObjectId = this.lookupGroupObjectIdByName(_groupUserInfo.Name);

        if (groupObjectId)
        {
            this.updateGroupObjectId(_groupUserInfo, groupObjectId);
        }
    }

    if (!groupObjectId || groupObjectId == guid2Str(emptyGuid()))
    {
        warning(strFmt("@D365FOAdminToolkit:EntraIdGroupObjectIdMissing", _groupUserInfo.id));
        totalErrors++;
        return;
    }

    // Normalise the target group ObjectId to lowercase for cache key comparison.
    groupObjectIdNorm = strLwr(groupObjectId);

    this.ensureTenantUserCacheLoaded();
    this.ensureUserGroupsCacheLoaded();

    tenantCacheEnum = tenantUserCache.getEnumerator();

    while (tenantCacheEnum.moveNext())
    {
        memberObjectIdKey = tenantCacheEnum.currentKey();

        if (!userGroupsCache || !userGroupsCache.exists(memberObjectIdKey))
        {
            skippedNotInCache++;
            continue;
        }

        memberGroupIds = userGroupsCache.lookup(memberObjectIdKey);
        inGroup = false;

        for (i = 1; i <= conLen(memberGroupIds); i++)
        {
            if (conPeek(memberGroupIds, i) == groupObjectIdNorm)
            {
                inGroup = true;
                break;
            }
        }

        if (!inGroup)
        {
            continue;
        }

        membersFetched++;

        try
        {
            graphUser = tenantCacheEnum.currentValue();

            select firstonly RecId from existingUser
                where existingUser.ObjectId == graphUser.ObjectID;

            if (existingUser.RecId)
            {
                skippedExisting++;
                continue;
            }

            str userSid = axaptaUserManager.getUserSid(
                graphUser.UserPrincipalName,
                Microsoft.Dynamics.ApplicationPlatform.Environment.EnvironmentFactory::GetApplicationEnvironment().get_Provisioning().get_AdminIdentityProvider());

            if (userSid)
            {
                select firstonly RecId from existingUser
                    where existingUser.sid == userSid;

                if (existingUser.RecId)
                {
                    skippedExisting++;
                    continue;
                }
            }

            if (!this.populateTmpUserFromGraphUser(graphUser, axaptaUserManager))
            {
                skippedLiveId++;
                continue;
            }

            if (!tmp.NetworkAlias)
            {
                skippedLiveId++;
                continue;
            }

            tmp.AxUserID = helper.generateUserID(tmp.NetworkAlias, selectedUsers);
            this.createUser(tmp, _groupUserInfo.id);
            created++;

            if (ADMParameters::find().SynchronousUserEntraIDGroupSync)
            {
                ADMEntraIdGroupUserSynchronization::synchronize(tmp.AxUserID);
            }
        }
        catch (Exception::Error)
        {
            errors++;
            warning(strFmt("@D365FOAdminToolkit:EntraIdUserImportFailed",
                memberObjectIdKey,
                _groupUserInfo.id));
        }
    }

    totalMembersFetched    += membersFetched;
    totalUsersCreated      += created;
    totalSkippedExisting   += skippedExisting;
    totalSkippedLiveId     += skippedLiveId;
    totalSkippedNotInCache += skippedNotInCache;
    totalErrors            += errors;
}
